/** web: existing LIVON topic categories mapped · partial: only services/policies · planned: nothing yet */
export function categoryStatus(c) {
  if (c.map.cat.length) return "web";
  if (c.map.svc.length || c.map.pol.length) return "partial";
  return "planned";
}

