for (const c of CATEGORIES) {
  const d = DOC[c.n];
  if (!d) continue;
  if (d.ko) c.ko = d.ko;
  if (d.en) c.en = d.en;
  c.lineKo = d.lineKo; c.lineEn = d.lineEn;
  if (d.noteKo) { c.noteKo = d.noteKo; c.noteEn = d.noteEn; }
  if (d.addKo) {
    for (let i = 0; i < d.addKo.length; i++) if (!c.topicsKo.includes(d.addKo[i])) { c.topicsKo.push(d.addKo[i]); c.topicsEn.push(d.addEn[i]); }
  }
}

